import chai from 'chai';
import {
  findViolations, generatePairs, samplePairs, stylesToCheck
} from '../../tooling/scripts/same-schedule.mjs';

const {expect} = chai;

// What a description says depends on the moments that fire, never on how
// the pattern was spelled (CLAUDE.md, "Conditions are about the set of
// values"), except for a tie a language's answers declare by name. Pairs of
// patterns are generated by family and classified by the answer key
// (tooling/scripts/reading/oracle.mjs), which shares no code with the
// library: two that fire at the same moments must be said with the same
// sentence, and two that fire at different moments with different ones,
// in every language and every named style. The test checks at most CAP
// pairs of each family, spread evenly through it (and every pair reported
// by hand); `npm run same-schedule` checks them all.
const CAP = 300;
const SHOWN = 12;
const SLOW = 180000;

let result = null;

function checked() {
  if (!result) {
    result = findViolations(samplePairs(generatePairs(), CAP));
  }

  return result;
}

function listed(found) {
  return found.slice(0, SHOWN).map(function line(item) {
    return `${item.style} (${item.family}): \`${item.a}\` «${item.sentenceA}»` +
      ` | \`${item.b}\` «${item.sentenceB}»`;
  }).join('\n') + (found.length > SHOWN ?
    `\n… and ${found.length - SHOWN} more` :
    '');
}

describe('the same schedule is said the same way:', function() {
  const codes = [...new Set(stylesToCheck().map((target) => target.code))];

  codes.forEach(function each(code) {
    describe(code, function() {
      it('says patterns that fire alike with the same sentence', function() {
        const found = checked().violations.filter((item) =>
          item.code === code && item.kind === 'equivalent');

        expect(found.length, listed(found)).to.equal(0);
      }, SLOW);

      it('says patterns that fire differently with different sentences',
        function() {
          const found = checked().violations.filter((item) =>
            item.code === code && item.kind === 'distinct');

          expect(found.length, listed(found)).to.equal(0);
        }, SLOW);
    });
  });
});
